-- Talents des domaines de classe (ameliorations), extraits de GarrTalent.db2 (7.3.5.26972) et
-- GarrTalentTree.db2 (classe de l arbre). Notre core ne chargeait pas ces donnees (03/10/2026).
DROP TABLE IF EXISTS garrison_class_hall_talent;
CREATE TABLE garrison_class_hall_talent (
  ID int unsigned NOT NULL, TreeID int unsigned NOT NULL, ClassID tinyint unsigned NOT NULL,
  Tier tinyint unsigned NOT NULL, UiOrder tinyint unsigned NOT NULL, Flags tinyint unsigned NOT NULL,
  ResearchDurationSecs int unsigned NOT NULL, ResearchCost int unsigned NOT NULL, ResearchCostCurrencyID int unsigned NOT NULL,
  ResearchGoldCost int unsigned NOT NULL, PerkSpellID int unsigned NOT NULL, PlayerConditionID int unsigned NOT NULL,
  RespecCost int unsigned NOT NULL, RespecCostCurrencyID int unsigned NOT NULL, RespecDurationSecs int unsigned NOT NULL,
  RespecGoldCost int unsigned NOT NULL, Name varchar(100) NOT NULL DEFAULT '', PRIMARY KEY (ID)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
